const works=[{id:'beat',cat:'Gaming',title:'别眨眼，接住这一拍。',desc:'跟着节奏，在光点经过中心时按下。你能有多准？',author:'Studio Small',time:'30 秒挑战',likes:248,plays:'12.8k',bg:'#e5dfff'},{id:'orbit',cat:'Science & Technology',title:'给宇宙一点小小的扰动',desc:'调整引力，看看轨道会发生怎样的变化。',author:'Kepler Lab',time:'3 分钟探索',likes:386,plays:'9.6k',bg:'#172331'},{id:'quiz',cat:'Knowledge',title:'你的直觉，真的可靠吗？',desc:'一道小问题，重新认识概率与直觉之间的距离。',author:'Mindfield',time:'1 分钟思考',likes:192,plays:'8.2k',bg:'#f3eaca'},{id:'wave',cat:'Simulation',title:'两道波，会相遇成什么？',desc:'改变频率，亲手制造一次建设性的干涉。',author:'Almost Physics',time:'2 分钟探索',likes:175,plays:'6.4k',bg:'#d7ebe9'},{id:'draw',cat:'Creative',title:'随手一划，灵感就开花。',desc:'把鼠标变成画笔，让对称替你完成另一半。',author:'Form & Play',time:'无限灵感',likes:321,plays:'7.1k',bg:'#f1d8cc'},{id:'social',cat:'Fun & Social',title:'如果是你，会按哪一个？',desc:'瞬间移动，还是时间暂停？看看你和朋友是否一样。',author:'What If Club',time:'10 秒选择',likes:163,plays:'5.9k',bg:'#e3edc9'}];
const cats=['All','Gaming','Science & Technology','Knowledge','Simulation','Creative','Fun & Social'];let selected='All',activeId='orbit',remixing=false;const likes=new Set();const states=new WeakMap();let toastTimer;function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2800)}
document.querySelector('#categories').innerHTML=cats.map((c,i)=>`<button class="${i?'':'selected'}" aria-pressed="${!i}" data-cat="${c}">${['✳ 全部','◈ Gaming','◎ Science & Technology','▤ Knowledge','∿ Simulation','✺ Creative','☺ Fun & Social'][i]}</button>`).join('');document.querySelector('#categories').addEventListener('click',e=>{if(!e.target.dataset.cat)return;selected=e.target.dataset.cat;document.querySelectorAll('[data-cat]').forEach(b=>{b.classList.toggle('selected',b.dataset.cat===selected);b.setAttribute('aria-pressed',b.dataset.cat===selected)});render()});
function escapeHtml(value){return String(value).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function stage(w){if(w.assetType)return importedStage(w);if(w.template)w={...w,id:w.template};if(w.id==='orbit')return `<div class="slice feature-stage" data-kind="orbit"><canvas aria-label="轨道交互示意图"></canvas><span class="slice-badge">↔ DRAG TO EXPLORE</span><label class="gravity">引力 <input aria-label="引力强度" type="range" min="20" max="200" value="100"><output>1.0×</output></label></div>`;return `<div class="slice" data-kind="${w.id}" style="background:${w.bg}"><canvas aria-label="${escapeHtml(w.title)}"></canvas><span class="slice-badge">${{beat:'● TAP TO PLAY',quiz:'? TRUST YOUR INSTINCT',wave:'↔ CHANGE THE FREQUENCY',draw:'✺ DRAW SOMETHING',social:'↗ PICK A SIDE'}[w.id]}</span>${w.id==='quiz'?'<div class="slice-msg"><strong>三次正面之后…</strong><p>下一次抛硬币，正面的概率是？</p></div>':w.id==='social'?'<div class="slice-msg"><strong>你会怎么选？</strong><p>只能保留一种超能力。</p></div>':w.id==='beat'?'<div class="slice-msg"><strong>Find your rhythm.</strong><p>光点抵达中心时，点击「接住」</p></div>':''}<div class="slice-controls">${{beat:'<button data-hit>接住这一拍 ↓</button><span data-score>0 分</span>',quiz:'<button data-answer="wrong">25%</button><button data-answer="right">50%</button><button data-answer="wrong">75%</button>',wave:'<label>频率 <input aria-label="波的频率" type="range" min="1" max="8" step="0.1" value="3"><output>3.0 Hz</output></label>',draw:'<span>拖动绘画 · 四向对称</span><button data-clear>清空 ↻</button>',social:'<button data-vote="a">瞬间移动 ↗</button><button data-vote="b">时间暂停 ◷</button>'}[w.id]}</div></div>`}
function render(){const list=works.filter(w=>selected==='All'||w.cat===selected);document.querySelector('#feed-label').innerHTML=`${selected==='All'?'为你发现':selected} <small>${list.length} 个可玩的想法</small>`;document.querySelector('#feed').innerHTML=list.map(w=>`<article class="card" id="card-${w.id}">${stage(w)}<div class="card-meta"><span>${w.cat.toUpperCase()}</span><span>${w.time}</span></div><h3>${escapeHtml(w.title)}</h3><p>${escapeHtml(w.desc)}</p><div class="card-author">${escapeHtml(w.author)} <span>· ${w.plays} 次体验</span></div><div class="card-actions"><button data-like="${w.id}" class="${likes.has(w.id)?'liked':''}" aria-pressed="${likes.has(w.id)}" aria-label="喜欢 ${escapeHtml(w.title)}">${likes.has(w.id)?'♥':'♡'} ${w.likes+(likes.has(w.id)?1:0)}</button><button data-share="${w.id}">↗ Share</button><button data-remix="${w.id}">⤨ Remix</button><button data-open="${w.id}">Open ↗</button></div></article>`).join('');initStages(document.querySelector('#feed'))}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.like){const id=b.dataset.like;likes.has(id)?likes.delete(id):likes.add(id);const w=works.find(w=>w.id===id);b.classList.toggle('liked',likes.has(id));b.setAttribute('aria-pressed',likes.has(id));b.textContent=`${likes.has(id)?'♥':'♡'} ${w.likes+(likes.has(id)?1:0)}`}if(b.dataset.open)openWork(b.dataset.open);if(b.dataset.remix)openWork(b.dataset.remix,true);if(b.dataset.share){if(works.find(w=>w.id===b.dataset.share)?.local){toast('这篇Slice仅保存在本机，尚未生成公开分享链接');return}const url=new URL(location.href);url.hash='work='+b.dataset.share;try{await navigator.clipboard.writeText(url.href);toast('Slice链接已复制，可以分享给朋友')}catch{toast('复制地址栏中的Slice链接即可分享');location.hash=url.hash}}});
document.querySelector('#trending-list').innerHTML=[works[0],works[1],works[4],works[2]].map((w,i)=>`<button class="trend" data-open="${w.id}"><span>0${i+1}</span><div><strong>${escapeHtml(w.title)}</strong><small>${w.cat} · ${w.plays} 次体验</small></div></button>`).join('');
const dialog=document.querySelector('#work-dialog');function openWork(id,remix=false){const w=works.find(w=>w.id===id);if(!w)return;if(remix&&w.assetType){openCreator(w);return}activeId=id;remixing=remix;document.querySelector('#dialog-mode').textContent=remix?'REMIX STUDIO · 本地实验':'PLAYGROUND · 完整体验';document.querySelector('#dialog-title').textContent=(remix?'改编：':'')+w.title;document.querySelector('#dialog-desc').textContent=remix?'调整强调色与节奏，制作你的版本。改编仅保留在当前窗口。':w.desc;document.querySelector('#dialog-stage').innerHTML=stage(w)+(remix?'<div class="remix-options"><label>强调色 <input id="remix-color" type="color" value="#bc77ee"></label><label>节奏 <input id="remix-speed" aria-label="改编动画速度" type="range" min="0.3" max="2" value="1" step="0.1"></label></div>':'');if(!dialog.open)dialog.showModal();initStages(dialog);if(remix){const state=states.get(dialog.querySelector('[data-kind]'));document.querySelector('#remix-color').oninput=e=>{state.color=e.target.value;dialog.querySelector('.slice').style.background=e.target.value+'44'};document.querySelector('#remix-speed').oninput=e=>state.speed=+e.target.value}}
document.querySelector('#close-dialog').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});document.querySelector('#reset-work').onclick=()=>openWork(activeId,remixing);document.querySelector('#next-work').onclick=()=>openWork(works[(works.findIndex(w=>w.id===activeId)+1)%works.length].id);
function initStages(root){root.querySelectorAll('[data-kind]').forEach(el=>{if(states.has(el))return;const s={kind:el.dataset.kind,t:0,v:1,score:0,color:null,speed:1,lines:[],drawing:false,cleared:false};states.set(el,s);const canvas=el.querySelector('canvas');const range=el.querySelector('input[type=range]');if(range)range.oninput=()=>{s.v=+range.value/(s.kind==='orbit'?100:1);el.querySelector('output').textContent=s.kind==='orbit'?s.v.toFixed(1)+'×':s.v.toFixed(1)+' Hz'};if(s.kind==='wave')s.v=3;el.querySelector('[data-hit]')?.addEventListener('click',()=>{const delta=Math.abs(Math.sin(s.t*2));const score=Math.round((1-delta)*100);s.score+=score;el.querySelector('[data-score]').textContent=`+${score} / 总分 ${s.score}`;el.querySelector('.slice-msg p').textContent=score>80?'Perfect! 完美踩点。':'再试一次，等它抵达中线。'});el.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{el.querySelector('.slice-msg strong').textContent=b.dataset.answer==='right'?'没错，是 50%！':'答案是 50%';el.querySelector('.slice-msg p').textContent='独立事件：前面的结果不会改变下一次的概率。';el.querySelectorAll('[data-answer]').forEach(x=>x.style.background=x.dataset.answer==='right'?'#ceff58':'#ffffff99')});el.querySelectorAll('[data-vote]').forEach(b=>b.onclick=()=>{el.querySelector('.slice-msg strong').textContent=b.dataset.vote==='a'?'下一站，全世界。':'把这一刻留住。';el.querySelector('.slice-msg p').textContent='你的选择已记录在这次体验中 · 分享给朋友比较答案';el.querySelectorAll('[data-vote]').forEach(x=>x.style.background=x===b?'#ceff58':'#ffffff99')});el.querySelector('[data-clear]')?.addEventListener('click',()=>{s.lines=[];s.cleared=true});if(s.kind==='draw'){canvas.style.touchAction='none';const point=e=>{const r=canvas.getBoundingClientRect();return [(e.clientX-r.left)/r.width,(e.clientY-r.top)/r.height]};canvas.onpointerdown=e=>{s.drawing=true;canvas.setPointerCapture(e.pointerId);s.lines.push([point(e)])};canvas.onpointermove=e=>{if(s.drawing)s.lines.at(-1).push(point(e))};canvas.onpointerup=canvas.onpointercancel=()=>s.drawing=false}const observer=new IntersectionObserver(entries=>s.visible=entries[0].isIntersecting);observer.observe(el);s.visible=true;let last=0;function frame(now){if(!el.isConnected){observer.disconnect();return}if(s.visible&&(!el.closest('dialog')||el.closest('dialog').open)){if(!matchMedia('(prefers-reduced-motion: reduce)').matches||s.kind==='beat')s.t+=Math.min((now-last)/1000||.016,.05)*s.speed;draw(canvas,s)}last=now;requestAnimationFrame(frame)}requestAnimationFrame(frame)})}
function draw(c,s){const r=c.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);if(!r.width||!r.height)return;if(c.width!==Math.round(r.width*d)||c.height!==Math.round(r.height*d)){c.width=Math.round(r.width*d);c.height=Math.round(r.height*d)}const x=c.getContext('2d');x.setTransform(d,0,0,d,0,0);const w=r.width,h=r.height;x.clearRect(0,0,w,h);const circle=(a,b,r,color)=>{x.beginPath();x.arc(a,b,r,0,Math.PI*2);x.fillStyle=color;x.fill()};if(s.kind==='orbit'){const cx=w*.55,cy=h*.48;for(let i=0;i<50;i++)circle((i*137.3)%w,(i*71.7)%h,i%4===0?1:.5,'#ffffff50');x.save();x.translate(cx,cy);x.rotate(-.25);for(let i=1;i<=5;i++){const a=Math.min(w*.41,h*.43)*i/5,b=a*.48; x.beginPath();x.ellipse(0,0,a,b,0,0,Math.PI*2);x.strokeStyle='#97b1cc36';x.lineWidth=1;x.stroke();const t=s.t*(.2+(.6/i))*Math.sqrt(s.v)+i*1.7;circle(Math.cos(t)*a,Math.sin(t)*b,4+i*.65,s.color||['','#c2ceef','#90d4ed','#cfed96','#aaa0d2','#f2c897'][i])}const g=x.createRadialGradient(0,0,1,0,0,44);g.addColorStop(0,'#e4ffad');g.addColorStop(.3,'#d1ff7380');g.addColorStop(1,'#d1ff7300');circle(0,0,44,g);circle(0,0,14,s.color||'#e0ff9f');x.restore()}else if(s.kind==='beat'){const y=h*.65;x.strokeStyle='#bdb2da';x.beginPath();x.moveTo(25,y);x.lineTo(w-25,y);x.stroke();x.strokeStyle='#766193';x.setLineDash([3,3]);x.beginPath();x.moveTo(w/2,y-27);x.lineTo(w/2,y+27);x.stroke();x.setLineDash([]);circle(w/2,y,21,'#ffffff70');circle(w/2+Math.sin(s.t*2)*(w/2-35),y,12,s.color||'#7651c7')}else if(s.kind==='wave'){for(let j=0;j<3;j++){x.beginPath();for(let i=0;i<w;i++){let a=Math.sin(i/w*Math.PI*2*s.v-s.t*1.8),b=Math.sin(i/w*Math.PI*5+s.t);let y=h*.48+(j===0?a:j===1?b:(a+b)*.65)*35;i?x.lineTo(i,y):x.moveTo(i,y)}x.strokeStyle=s.color||['#51a5a3','#99bc79','#215b5f'][j];x.lineWidth=j===2?3:1.5;x.stroke()}x.font='12px sans-serif';x.fillStyle='#497370';x.fillText('SUPERPOSITION / 波的叠加',20,h-68)}else if(s.kind==='draw'){x.lineWidth=2;x.strokeStyle=s.color||'#ae613e';const lines=s.lines.length?s.lines:s.cleared?[]:[Array.from({length:180},(_,i)=>{let t=i/18;return [.5+Math.cos(t*2.1)*Math.sin(t*.35)*.25,.5+Math.sin(t*2.1)*Math.sin(t*.35)*.3]})];for(let l of lines)for(let a of [-1,1])for(let b of [-1,1]){x.beginPath();l.forEach((p,i)=>{let px=(.5+(p[0]-.5)*a)*w,py=(.5+(p[1]-.5)*b)*h;i?x.lineTo(px,py):x.moveTo(px,py)});x.stroke()}}}
render();initStages(document);if(location.hash.startsWith('#work='))openWork(location.hash.slice(6));window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#work='))openWork(location.hash.slice(6))});
